solution.solution.cpp:
#include <cctype>
#include <string>
#include <vector>

static bool absolute(const std::string& p)
{
    return p.size() >= 3 && std::isalpha(static_cast<unsigned char>(p[0])) && p[1] == ':' && (p[2] == '\\' || p[2] == '/');
}

std::string normalizePath(const std::string& path)
{
    std::string p{ path };
    for (char& c : p) if (c == '/') c = '\\';
    std::string prefix;
    std::size_t start{ 0 };
    if (absolute(p)) { prefix = p.substr(0, 2); start = 3; }
    std::vector<std::string> parts;
    std::string part;
    auto push = [&](const std::string& s) -> bool {
        if (s.empty() || s == ".") return true;
        if (s == "..") { if (parts.empty()) return false; parts.pop_back(); return true; }
        parts.push_back(s);
        return true;
    };
    for (std::size_t i{ start }; i <= p.size(); ++i)
    {
        if (i == p.size() || p[i] == '\\')
        {
            if (!push(part)) return "";
            part.clear();
        }
        else part += p[i];
    }
    std::string out{ prefix.empty() ? "" : prefix + "\\" };
    for (std::size_t i{ 0 }; i < parts.size(); ++i) { if (i) out += '\\'; out += parts[i]; }
    return out;
}

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

bool safePluginPath(const std::string& pluginFolder, const std::string& candidate)
{
    if (!absolute(candidate) || !absolute(pluginFolder)) return false;
    const std::string folder{ lower(normalizePath(pluginFolder)) };
    const std::string file{ lower(normalizePath(candidate)) };
    if (folder.empty() || file.empty()) return false;
    const std::string inside{ folder.back() == '\\' ? folder : folder + "\\" };
    if (file.size() <= inside.size() || file.compare(0, inside.size(), inside) != 0) return false;
    return file.size() > 4 && file.compare(file.size() - 4, 4, ".dll") == 0;
}

unitTests:
TEST("normalise") { CHECK_EQ(normalizePath("C:\\Games//Xenon\\plugins\\.\\fog\\..\\fog.dll"), std::string("C:\\Games\\Xenon\\plugins\\fog.dll")); }
TEST("trailing backslash") { CHECK_EQ(normalizePath("C:\\Games\\"), std::string("C:\\Games")); CHECK_EQ(normalizePath("C:\\"), std::string("C:\\")); }
TEST("too many ..") { CHECK_EQ(normalizePath("C:\\a\\..\\..\\b"), std::string("")); CHECK_EQ(normalizePath("a\\..\\..\\b"), std::string("")); }
TEST("relative paths") { CHECK_EQ(normalizePath("plugins\\.\\fog.dll"), std::string("plugins\\fog.dll")); }
TEST("a plugin inside") { CHECK(safePluginPath("C:\\Games\\Xenon\\plugins", "C:\\Games\\Xenon\\plugins\\fog\\fog.dll")); CHECK(safePluginPath("C:\\Games\\Xenon\\plugins\\", "c:/games/xenon/PLUGINS/fog.DLL")); }
TEST("escaping the folder") { CHECK(!safePluginPath("C:\\Games\\Xenon\\plugins", "C:\\Games\\Xenon\\plugins\\..\\..\\Windows\\evil.dll")); }
TEST("a sibling folder with a similar name") { CHECK(!safePluginPath("C:\\Games\\Xenon\\plugins", "C:\\Games\\Xenon\\plugins-old\\fog.dll")); }
TEST("relative and wrong extension") { CHECK(!safePluginPath("C:\\Games\\Xenon\\plugins", "plugins\\fog.dll")); CHECK(!safePluginPath("C:\\Games\\Xenon\\plugins", "C:\\Games\\Xenon\\plugins\\fog.exe")); CHECK(!safePluginPath("C:\\Games\\Xenon\\plugins", "C:\\Games\\Xenon\\plugins")); }

